import hashlib

class BloomFilter:
    def __init__(self, size: int = 1024, num_hashes: int = 3):
        self.size = size
        self.num_hashes = num_hashes
        self.bits = bytearray(size)

    def _hashes(self, item: str):
        for seed in range(self.num_hashes):
            digest = hashlib.sha256(f'{seed}:{item}'.encode()).hexdigest()
            yield int(digest, 16) % self.size

    def add(self, item: str) -> None:
        for pos in self._hashes(item):
            self.bits[pos] = 1

    def might_contain(self, item: str) -> bool:
        return all(self.bits[pos] == 1 for pos in self._hashes(item))

import heapq

class DeadlineScheduler:
    def __init__(self):
        self._queue = []
        self._seq = 0

    def schedule(self, deadline: float, task_fn) -> None:
        self._seq += 1
        heapq.heappush(self._queue, (deadline, self._seq, task_fn))

    def pop_next(self):
        if not self._queue:
            return None
        deadline, _, task_fn = heapq.heappop(self._queue)
        return deadline, task_fn
